{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Aromatic practices that may support your balance</title>
  <meta name="description" content="Aromatherapy sessions, custom blends, and mindful mini-practices that may support ease and focus.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body>
  <header class="site-header">
    <div class="brand">
      <svg class="logo" viewBox="0 0 48 48" aria-hidden="true"><rect width="48" height="48" rx="8" fill="url(#g)"/><defs><linearGradient id="g" x1="0" x2="1"><stop offset="0" stop-color="#EFE6D6"/><stop offset="1" stop-color="#DCE8E2"/></linearGradient></defs></svg>
      <div>
        <h1>{{BUSINESS_NAME}}</h1>
        <p class="tag">{{TAGLINE}}</p>
      </div>
    </div>
    <nav class="nav">
      <a href="/index.html">Home</a>
      <a href="/services.html">Offerings</a>
      <a href="/blends.html">Blends Lab</a>
      <a href="/shop.html">Boutique</a>
      <a href="/pricing.html">Rates</a>
      <a href="/about.html">About</a>
      <a href="/book.html">Book</a>
      <a href="/contact.html">Connect</a>
    </nav>
    <a class="cta small" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
  </header>

  <main>
    <!-- Hero -->
    <section class="hero">
      <svg class="hero-pattern" aria-hidden="true" focusable="false">
        <use href="assets/img/pattern.svg#pattern" />
      </svg>
      <div class="hero-inner">
        <h2>Intentional scent practices that may support calm, focus, and evening ease</h2>
        <p>Curated sessions, bespoke blends, and short daily cues for people who want practical aromatic tools. Safety-first guidance included.</p>
        <div class="hero-actions">
          <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn ghost" href="/book.html">Schedule a consult</a>
        </div>
      </div>
    </section>

    <!-- Diagnostic: Mood-to-Method selector -->
    <section class="diagnostic" id="diagnostic">
      <div class="diag-left">
        <h3>What are you feeling right now?</h3>
        <p>Pick a mood and we’ll suggest a gentle aromatherapy approach and a simple next step.</p>
        <div class="mood-grid" id="moodGrid">
          <button class="mood" data-key="stressed">Stressed</button>
          <button class="mood" data-key="foggy">Foggy</button>
          <button class="mood" data-key="tired">Tired</button>
          <button class="mood" data-key="tingly">On edge</button>
          <button class="mood" data-key="cheery">Celebratory</button>
        </div>
      </div>
      <div class="diag-right" id="moodResult">
        <h4 class="method-title">Choose a mood</h4>
        <p class="method-desc">We’ll describe a sensory approach and a small, safe step you can try.</p>
        <ul class="method-list">
          <li class="blend-sample"><strong>Sample blend:</strong> <span id="blendSample">—</span></li>
          <li class="method-note"><strong>Approach:</strong> <span id="methodApproach">—</span></li>
          <li class="safety"><strong>Safety note:</strong> <span id="safetyNote">Dilute appropriately. Patch test. Avoid near infants or unwell pets. See FAQ.</span></li>
        </ul>
        <div class="diag-actions">
          <a id="moodCTA" class="btn primary" href="{{PRIMARY_CTA_URL}}">Start a simple practice</a>
          <a class="btn ghost" href="/blends.html">Explore blends</a>
        </div>
      </div>
    </section>

    <!-- Plan: offerings overview (order different from other pages) -->
    <section class="plan">
      <div class="plan-intro">
        <h3>Signature paths</h3>
        <p>Three approachable ways to work with scent that may support daily balance and clarity — each coached for safety and ease.</p>
      </div>
      <div class="plans">
        <article class="plan-card">
          <h4>Single Session — Scent Tune</h4>
          <p>One guided session (60 min) to introduce practices, assess preferences, and build a short at-home ritual.</p>
          <div class="plan-actions"><a class="btn ghost" href="/book.html">Book a Scent Tune</a></div>
        </article>
        <article class="plan-card">
          <h4>Cycle Series — Rhythm Reset (3)</h4>
          <p>A three-visit series to establish rhythm-based scent cues and simple micro-habits to support daily transitions.</p>
          <div class="plan-actions"><a class="btn ghost" href="/pricing.html">See packages</a></div>
        </article>
        <article class="plan-card">
          <h4>Custom Blend Plan</h4>
          <p>Personalized blend creation with written guidance for safe dilution and use around family and pets.</p>
          <div class="plan-actions"><a class="btn ghost" href="/blends.html">Design a blend</a></div>
        </article>
      </div>
    </section>

    <!-- Micro habits -->
    <section class="micro-habits">
      <h3>Small rituals you can try today</h3>
      <div class="habits">
        <div class="habit">
          <h5>60-second Reset</h5>
          <p>Inhale gently from a diffuser or tissue for three slow breaths. Ground with your senses.</p>
        </div>
        <div class="habit">
          <h5>Transition Cue</h5>
          <p>Before a new task, spritz a diluted mist to mark a start — consistency helps cue intention.</p>
        </div>
        <div class="habit">
          <h5>Evening Wind-down</h5>
          <p>Choose a calming blend and inhale while dimming lights to signal rest rituals.</p>
        </div>
      </div>
    </section>

    <!-- Pricing: comparator with monthly vs package toggle -->
    <section class="pricing" id="pricing">
      <div class="pricing-header">
        <h3>Rates & Bundles</h3>
        <p>Choose a rhythm — monthly ongoing support or one-time packages. Animated totals help compare value.</p>
        <div class="toggle">
          <label class="switch">
            <input id="priceToggle" type="checkbox">
            <span class="slider"></span>
          </label>
          <span class="toggle-label"><strong id="toggleLabel">Monthly</strong> vs Package</span>
        </div>
      </div>

      <div class="price-grid">
        <div class="price-card">
          <h4>Intro Inhale</h4>
          <p class="price-amount" data-month="45" data-package="120">$<span class="num">45</span></p>
          <p class="price-note">One-off consultation to get started.</p>
          <a class="btn primary" href="/book.html">Book Intro</a>
        </div>

        <div class="price-card">
          <h4>Rhythm Reset</h4>
          <p class="price-amount" data-month="85" data-package="240">$<span class="num">85</span></p>
          <p class="price-note">Monthly coaching or save with a 3-session package.</p>
          <a class="btn primary" href="/pricing.html">Choose Rhythm</a>
        </div>

        <div class="price-card">
          <h4>Custom Blend Plan</h4>
          <p class="price-amount" data-month="120" data-package="320">$<span class="num">120</span></p>
          <p class="price-note">Includes two custom blends and usage plan.</p>
          <a class="btn primary" href="/blends.html">Start Blend</a>
        </div>
      </div>
      <p class="pricing-foot">All work is non-medical and may support wellbeing. See FAQ for safety and dilution notes.</p>
    </section>

    <!-- CTA -->
    <section class="cta-large">
      <div>
        <h3>Ready to try a small aromatic practice?</h3>
        <p>Start with a guided session or ask for a free sample plan tailored to your day.</p>
        <a class="btn big" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="footer-inner">
      <div>
        <p>&copy; <span id="year"></span> {{BUSINESS_NAME}} • {{CITY}}, {{STATE}}</p>
        <p>Call: {{PHONE}} • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      </div>
      <nav class="legal">
        <a href="/about.html">About</a>
        <a href="/pricing.html">Pricing</a>
        <a href="/contact.html">FAQ & Safety</a>
      </nav>
    </div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
