{"path":"assets/css/styles.css","content":"/* Minimal artisan styles for aromatic practice site */
:root{--bg:#FBFAF6;--muted:#7B7B7B;--accent:#6A8F7F;--accent-2:#D6BFA6;--card:#FFFFFF;--glass:rgba(255,255,255,0.6)}
*{box-sizing:border-box}
body{font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;line-height:1.45;margin:0;background:linear-gradient(180deg,var(--bg),#F2F6F4);color:#222}
.site-header{display:flex;align-items:center;justify-content:space-between;padding:18px 28px;background:linear-gradient(90deg,rgba(255,255,255,0.6),transparent);position:sticky;top:0;backdrop-filter:blur(6px);z-index:10}
.brand{display:flex;gap:12px;align-items:center}
.logo{width:48px;height:48px}
.brand h1{font-size:16px;margin:0}
.tag{font-size:12px;color:var(--muted);margin:0}
.nav{display:flex;gap:12px}
.nav a{color:#333;text-decoration:none;font-size:14px;padding:8px}
.cta.small{background:var(--accent);color:#fff;padding:8px 12px;border-radius:8px;text-decoration:none}
.hero{display:grid;grid-template-columns:1fr;align-items:center;padding:48px 28px;background-image:url('assets/img/pattern.svg');background-repeat:no-repeat;background-position:right top}
.hero-inner{max-width:900px}
.hero h2{font-size:28px;margin:0 0 10px;color:#1f2d2a}
.hero p{color:var(--muted);margin:0 0 18px}
.btn{display:inline-block;padding:10px 16px;border-radius:10px;text-decoration:none;font-weight:600}
.btn.primary{background:var(--accent);color:#fff}
.btn.ghost{background:transparent;border:1px solid rgba(0,0,0,0.08)}
.btn.big{padding:14px 22px;font-size:16px}
.diagnostic{display:grid;grid-template-columns:1fr 1fr;gap:18px;padding:28px;background:linear-gradient(180deg,transparent,rgba(255,255,255,0.7))}
.mood-grid{display:flex;flex-wrap:wrap;gap:10px;margin-top:12px}
.mood{padding:10px 12px;border-radius:10px;border:1px solid #eee;background:#fff;cursor:pointer}
.mood.active{box-shadow:0 6px 18px rgba(106,143,127,0.12);transform:translateY(-4px)}
.diag-right{background:var(--card);padding:16px;border-radius:12px}
.method-title{margin:0 0 6px}
.method-desc{color:var(--muted);margin:0 0 12px}
.method-list{list-style:none;padding:0;margin:0 0 12px}
.method-list li{margin:6px 0}
.pricing{padding:28px;background:linear-gradient(180deg,#fff,transparent)}
.pricing-header{display:flex;align-items:center;gap:18px}
.toggle{display:flex;align-items:center;gap:12px;margin-left:auto}
.switch{position:relative;display:inline-block;width:46px;height:26px}
.switch input{opacity:0;width:0;height:0}
.slider{position:absolute;cursor:pointer;top:0;left:0;right:0;bottom:0;background:#ddd;border-radius:34px}
.slider:before{position:absolute;content:"";height:20px;width:20px;left:3px;bottom:3px;background:white;border-radius:50%;transition:transform 0.25s}
.switch input:checked + .slider{background:var(--accent)}
.switch input:checked + .slider:before{transform:translateX(20px)}
.price-grid{display:flex;gap:12px;margin-top:18px}
.price-card{flex:1;background:var(--card);padding:16px;border-radius:12px;text-align:center}
.price-amount{font-size:20px;margin:8px 0}
.price-amount .num{font-weight:700}
.pricing-foot{color:var(--muted);font-size:13px;margin-top:12px}
.plan{padding:28px}
.plans{display:flex;gap:12px}
.plan-card{flex:1;background:var(--card);padding:16px;border-radius:12px}
.micro-habits{padding:28px;background:linear-gradient(90deg,transparent,#FFF7EE)}
.habits{display:flex;gap:12px}
.habit{flex:1;background:var(--card);padding:12px;border-radius:12px}
.cta-large{padding:28px;background:linear-gradient(180deg,#F4F7F6,#fff);text-align:center}
.site-footer{padding:18px 28px;border-top:1px solid #eee;background:transparent}
.footer-inner{display:flex;justify-content:space-between;align-items:center}
.legal a{margin-left:10px;color:var(--muted)}
@media(max-width:900px){.diagnostic{grid-template-columns:1fr}.price-grid{flex-direction:column}.plans{flex-direction:column}.nav{display:none}.hero h2{font-size:22px}}
/* subtle animated highlight for mood result */
.mood-animate{transition:all 300ms ease}
/* pattern reference fallback */
.hero-pattern{position:absolute;right:12px;top:12px;width:210px;height:210px;opacity:0.12}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Pricing Comparator
  const toggle = document.getElementById('priceToggle');
  const toggleLabel = document.getElementById('toggleLabel');
  const priceNums = Array.from(document.querySelectorAll('.price-amount .num'));
  const priceCards = Array.from(document.querySelectorAll('.price-amount'));

  function animateNumber(el, start, end, duration){
    const startTime = performance.now();
    function tick(now){
      const t = Math.min(1,(now-startTime)/duration);
      const eased = t<.5?2*t*t: -1 + (4-2*t)*t; // simple ease
      const val = Math.round(start + (end-start)*eased);
      el.textContent = val;
      if(t<1) requestAnimationFrame(tick);
    }
    requestAnimationFrame(tick);
  }

  function refreshPrices(isPackage){
    priceCards.forEach((card)=>{
      const numEl = card.querySelector('.num');
      const month = Number(card.getAttribute('data-month'))||0;
      const pack = Number(card.getAttribute('data-package'))||0;
      const from = Number(numEl.textContent)||month;
      const to = isPackage?pack:month;
      animateNumber(numEl, from, to, 500);
    });
    toggleLabel.textContent = isPackage? 'Package':'Monthly';
  }

  toggle.addEventListener('change', (e)=>{
    refreshPrices(e.target.checked);
  });

  // initialize
  refreshPrices(false);

  // Mood-to-Method selector
  const moods = {
    stressed:{title:'Soothing anchor',desc:'Short grounding inhalations and a green-woody touch to ease intensity.',blend:'Lavender + Petitgrain (gentle)',approach:'Three slow belly breaths with scent at the first exhale','safety':'Dilute 1-2% for topical use. Patch test.'},
    foggy:{title:'Clarity cue',desc:'Bright citrus notes to gently reorient attention without overstimulation.',blend:'Sweet Orange + Rosemary (diffuse briefly)',approach:'Diffuse for 10 minutes before focused work','safety':'Avoid direct ingestion; keep away from birds.'},
    tired:{title:'Evening ease',desc:'Warm, soft aromas that may signal downshift and rest when used at low concentration.',blend:'Chamomile CO2 + Bergamot',approach:'Diffuse low volume during dimming lights','safety':'Not for use with infants; consult if pregnant.'},
    tingly:{title:'Calm close',desc:'Low-dose grounding notes and breath pacing to ease nervous energy.',blend:'Cedarwood + Mandarin',approach:'Inhale from tissue for 6 slow breaths','safety':'Patch test for skin sensitivity.'},
    cheery:{title:'Elevated ease',desc:'Light floral-citrus for celebratory ease that still feels steady.',blend:'Neroli + Grapefruit',approach:'Diffuse sparingly during a small celebration','safety':'Keep away from curious pets; dilute for sprays.'}
  };

  const moodButtons = document.querySelectorAll('.mood');
  const titleEl = document.querySelector('.method-title');
  const descEl = document.querySelector('.method-desc');
  const blendEl = document.getElementById('blendSample');
  const approachEl = document.getElementById('methodApproach');
  const safetyEl = document.getElementById('safetyNote');
  const moodCTA = document.getElementById('moodCTA');

  function setMood(key, btn){
    const data = moods[key];
    if(!data) return;
    // animate text change
    [titleEl,descEl,blendEl,approachEl,safetyEl].forEach(el=>{
      el.classList.add('mood-animate');
      setTimeout(()=>el.classList.remove('mood-animate'),350);
    });
    titleEl.textContent = data.title;
    descEl.textContent = data.desc;
    blendEl.textContent = data.blend;
    approachEl.textContent = data.approach;
    safetyEl.textContent = data.safety + ' See FAQ for dilution and pets.';
    // update CTA verb and url param
    moodCTA.textContent = {
      stressed:'Try a calming session',
      foggy:'Try a clarity mini',
      tired:'Try a gentle wind-down',
      tingly:'Try a short grounding',
      cheery:'Try a bright cue'
    }[key] || 'Start a practice';
    // add query param to CTA link for tracking
    const base = '{{PRIMARY_CTA_URL}}';
    moodCTA.setAttribute('href', base + '?mood=' + encodeURIComponent(key));

    // visual state
    moodButtons.forEach(b=>b.classList.remove('active'));
    if(btn) btn.classList.add('active');
  }

  moodButtons.forEach(btn=>{
    btn.addEventListener('click', function(){
      setMood(this.getAttribute('data-key'), this);
    });
  });

  // footer year
  document.getElementById('year').textContent = new Date().getFullYear();

})();"} 
